+        if (!ext) {
+            file.resume(); // drain so the request can finish
+            return fail(400, 'Unsupported image type');
+        }
+
+        const uploadsDir = path.join(missionDir, 'CardPlugin', 'uploads');
+        try {
+            fs.mkdirSync(uploadsDir, { recursive: true });
+        } catch (err) {
+            file.resume();
